"""Packs the .glb models next to this file into docs/showcase/js/glb.js.

The guide page opens straight from disk, where a script cannot fetch a file, so the models
travel inside a script as base64. build.py runs this file; it also runs on its own with any
Python 3, for example: blender --background --python assets/models/embed.py
"""
import base64
import glob
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, '..', '..', 'docs', 'showcase', 'js', 'glb.js')

lines = [
    "'use strict';",
    '// Generated by assets/models/embed.py from assets/models/*.glb. Do not edit by hand.',
]
for path in sorted(glob.glob(os.path.join(HERE, '*.glb'))):
    name = os.path.splitext(os.path.basename(path))[0]
    with open(path, 'rb') as f:
        lines.append("RC.glb('%s', '%s');" % (name, base64.b64encode(f.read()).decode('ascii')))
with open(OUT, 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(lines) + '\n')
print('embed.py: wrote %d models to %s' % (len(lines) - 2, os.path.normpath(OUT)))
